  for(const block of content.blocks){const s=raw.letterSessions?.[block.id];if(!s||!Number.isInteger(s.step)||s.step<0||s.step>4||!Array.isArray(s.choices)||s.choices.length!==2||!s.choices.every(ids=>Array.isArray(ids)&&ids.length===2&&new Set(ids).size===2&&ids.every(id=>block.letters.includes(id))))continue;next.letterSessions[block.id]={step:s.step,choices:s.choices.map(ids=>[...ids]),hint:Number.isInteger(s.hint)?Math.max(0,Math.min(2,s.hint)):0,errors:Number.isInteger(s.errors)?Math.max(0,Math.min(1000,s.errors)):0};}
