  host.innerHTML='<div class="offlineSessionBar"><b>Lettere italiano / inglese</b><button type="button" id="offlineLettersPause">⏸ Pausa</button></div><h3 tabindex="-1">'+(q.model?'Stessa lettera, due lingue':letterReading?'Guarda la lettera e scegli':'Ascolta il nome inglese')+'</h3><p id="offlineLetterMode"></p><div id="offlineLetterModel" class="offlineBigLetter" '+(!q.model&&!letterReading?'hidden':'')+'>'+q.row.id+' <small>'+q.row.lower+'</small></div><div class="offlineLetterAudio"><button type="button" id="offlineLetterItalian">🔊 Nome italiano'+(!q.model?' · un aiuto':'')+'</button><button type="button" id="offlineLetterEnglish">🔊 Nome inglese</button><button type="button" id="offlineLetterStop">Ferma audio</button></div><button type="button" id="offlineLetterVerify" '+(!q.model&&!s.hint?'hidden':'')+'>Un adulto ha controllato il nome inglese di '+q.row.id+'</button><p id="offlineLetterVoiceStatus" role="status"></p><div id="offlineLetterExercise">'+(q.model?'<button type="button" id="offlineLetterContinue">Continua con calma</button>':'<div class="offlineLetterChoices" role="group" aria-label="Scegli fra due lettere">'+q.choices.map(id=>'<button type="button" data-offline-letter="'+id+'">'+id+' <small>'+id.toLowerCase()+'</small></button>').join('')+'</div><button type="button" id="offlineLetterRead">Preferisco leggere · un aiuto</button>')+'</div><div id="offlineLetterFeedback" role="status" aria-live="polite"></div><button type="button" id="offlineLetterNext" hidden>Continua →</button>';
  host.querySelector('#offlineLettersPause').onclick=intro;host.querySelector('#offlineLetterStop').onclick=stop;host.querySelector('#offlineLetterNext').onclick=drawLetters;host.querySelector('#offlineLetterContinue')?.addEventListener('click',()=>submitLetter(q.row.id));host.querySelectorAll('[data-offline-letter]').forEach(b=>b.onclick=()=>submitLetter(b.dataset.offlineLetter));host.querySelector('#offlineLetterRead')?.addEventListener('click',letterHint);
