 function sayLetter(lang){if(locked)return;stop();const q=letterQuestion(),voice=selectedVoice(lang);if(!voice)return;const generation=speechGeneration,u=new SpeechSynthesisUtterance(lang==='it-IT'?q.row.it:q.row.en);u.voice=voice;u.lang=voice.lang;u.rate=.8;const key=voiceKey(),block=letterBlock,step=q.s.step;u.onend=()=>{if(generation!==speechGeneration||panel.hidden||block!==letterBlock||state.letterSessions[block].step!==step)return;if(lang==='en-GB'){auditioned.add(key+':'+q.row.id);letterAudioUsed=true;}updateLetterControls();};u.onerror=()=>{if(generation!==speechGeneration||block!==letterBlock||panel.hidden)return;if(!q.model){letterReading=true;letterAudioUsed=false;host.querySelector('#offlineLetterModel').hidden=false;host.querySelector('h3').textContent='Guarda la lettera e scegli';}updateLetterControls();host.querySelector('#offlineLetterVoiceStatus').textContent='Audio non disponibile: continuiamo in lettura, senza fingere una prova di ascolto.';};speechSynthesis.speak(u);}
